{
  "root_causes": [
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, value FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='user' ORDER BY time",
          "claim": "The user deployment reports 0 available replicas at every sample across the abnormal window, against desired 1."
        },
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'user%' ORDER BY time",
          "claim": "The user pod's restart counter climbs from 4 to 6 in the abnormal window; the normal period shows 0 restarts."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) AS n, avg(c.duration)/1e6 AS avg_ms FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.service_name='frontend' AND c.attr_span_kind='Client' AND c.span_name='user.User/CheckUser' AND s.span_id IS NULL",
          "claim": "201 frontend calls to user.CheckUser have no server span in user and return in about 0.02 ms, i.e. they fail immediately."
        },
        {
